package vn.edu.hunre.nhom11.carrental.payment.domain;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import vn.edu.hunre.nhom11.carrental.booking.domain.Booking;
@Entity @Table(name="payments")public class Payment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Booking booking;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Enumerated(EnumType.STRING)private Method method;@Enumerated(EnumType.STRING)private Status status=Status.SUCCESS;private String transactionCode;private Instant createdAt=Instant.now();public enum Method{CASH,BANK_TRANSFER,MOMO,VNPAY}public enum Status{PENDING,SUCCESS,FAILED,REFUNDED}public Long getId(){return id;}public Booking getBooking(){return booking;}public void setBooking(Booking v){booking=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public Method getMethod(){return method;}public void setMethod(Method v){method=v;}public Status getStatus(){return status;}public void setStatus(Status v){status=v;}public String getTransactionCode(){return transactionCode;}public void setTransactionCode(String v){transactionCode=v;}public Instant getCreatedAt(){return createdAt;}}

